"use client";
import {useRouter} from "next/navigation";
import Link from "next/link";
import {useState,useTransition} from "react";
import {Handshake,ArrowUpRight} from "lucide-react";
import {removeCrossStoreFeature,respondToCrossStoreRequest} from "@/app/actions/cross-store";
import type {CrossStoreOutgoingRow,CrossStoreRequestRow} from "@/lib/cross-store/types";
import {orderDate} from "@/lib/vendor/order-workspace";
import s from "./business-workspace.module.css";
export default function PartnerRequestsClient({initialIncoming,initialOutgoing}:{initialIncoming:CrossStoreRequestRow[];initialOutgoing:CrossStoreOutgoingRow[]}){
 const router=useRouter(),[pending,startTransition]=useTransition();const [view,setView]=useState("incoming"),[status,setStatus]=useState("all"),[search,setSearch]=useState(""),[error,setError]=useState(""),[notice,setNotice]=useState(""),[confirm,setConfirm]=useState<string|null>(null);
 const rows=(view==="incoming"?initialIncoming.map(r=>({...r,partner:r.requestingStoreName})):initialOutgoing.map(r=>({...r,partner:r.targetStoreName}))).filter(r=>(status==="all"||status===r.status)&&`${r.partner} ${r.item?.name??""}`.toLowerCase().includes(search.toLowerCase().trim()));
 function run(action:()=>Promise<{ok:boolean;error?:string}>,message:string){setError("");setNotice("");startTransition(async()=>{try{const result=await action();if(!result.ok){setError(result.error??"The change could not be saved.");return;}setConfirm(null);setNotice(message);router.refresh();}catch{setError("The change could not be saved. Please try again.");}});}
 return <div className={s.stack}>
  <div className={s.grid}>{[{label:"Waiting for you",count:initialIncoming.filter(r=>r.status==="PENDING").length,view:"incoming",status:"PENDING"},{label:"Your items featured elsewhere",count:initialIncoming.filter(r=>r.status==="APPROVED").length,view:"incoming",status:"APPROVED"},{label:"Partners on your storefront",count:initialOutgoing.filter(r=>r.status==="APPROVED").length,view:"outgoing",status:"APPROVED"}].map(card=><button key={card.label} className={s.card} style={{textAlign:"left",cursor:"pointer"}} onClick={()=>{setView(card.view);setStatus(card.status);}}><p className={s.label}>{card.label}</p><p className={s.metric} style={{marginTop:12}}>{card.count}</p></button>)}</div>
  <section className={s.hero}><div className={s.row}><div><h2 className={s.heading}>A recommendation that works both ways.</h2><p className={s.muted}>Browse a partner’s listing and choose “Feature on my store”. The owner approves before it appears on your storefront.</p><p className={s.muted} style={{marginTop:8}}>The listing and checkout stay with the original seller. Featuring an item does not create a commission or revenue-sharing agreement. Either store can end the feature.</p></div><Handshake size={42} aria-hidden/></div><div className={s.miniLinks}><Link className={s.secondary} href="/shop">Explore products ↗</Link><Link className={s.secondary} href="/services">Explore services ↗</Link><Link className={s.secondary} href="/events">Explore events ↗</Link></div></section>
  <section className={s.card}><nav className={s.tabs} aria-label="Collaboration direction"><button aria-pressed={view==="incoming"} onClick={()=>{setView("incoming");setStatus("all");}}>Requests for your items</button><button data-tour="collab-outgoing-tab" aria-pressed={view==="outgoing"} onClick={()=>{setView("outgoing");setStatus("all");}}>Items you want to feature</button></nav><div className={s.toolbar}><input className={s.input} aria-label="Search collaborations" placeholder="Search partner or item…" value={search} onChange={e=>setSearch(e.target.value)}/><select className={s.select} aria-label="Collaboration status" value={status} onChange={e=>setStatus(e.target.value)}><option value="all">All statuses</option><option value="PENDING">Pending</option><option value="APPROVED">Approved</option><option value="REJECTED">Closed</option></select></div>
  {error&&<p className={s.error} role="alert">{error}</p>}{notice&&<p className={s.muted} role="status">{notice}</p>}
  <div data-tour={view==="incoming"?"collab-incoming":"collab-outgoing"}>{!rows.length?<div className={s.empty}><Handshake size={34} style={{margin:"0 auto 14px"}}/><h2 className={s.heading}>No collaborations in this view</h2><p>{view==="incoming"?"Requests from other stores will appear here. Share your storefront to help partners find your work.":"Discover a complementary listing and request to feature it on your store."}</p></div>:rows.map(row=><article key={row.relationshipId} className={s.divider}><div className={s.row}><div><p className={s.label}>{row.partner}</p><h3 className={s.heading} style={{marginTop:8}}>{row.item?.name??"Unavailable item"}</h3><p className={s.muted}>{row.item?.type.toLowerCase()??"Listing"} · Requested {orderDate(row.createdAt)}</p></div><span className={`${s.badge} ${row.status==="PENDING"?s.warning:""}`}>{row.status==="REJECTED"?"Closed":row.status==="APPROVED"?"Approved":"Awaiting approval"}</span></div><div className={s.miniLinks}>{row.item?.href&&<Link className={s.secondary} href={row.item.href}>View listing <ArrowUpRight size={15}/></Link>}{view==="incoming"&&row.status==="PENDING"?<><button disabled={pending||!row.item?.href} className={s.button} onClick={()=>run(()=>respondToCrossStoreRequest(row.relationshipId,"APPROVED"),"Feature approved. The partner can now display your published item.")}>Approve feature</button><button disabled={pending} className={s.secondary} onClick={()=>run(()=>respondToCrossStoreRequest(row.relationshipId,"REJECTED"),"Request declined.")}>Decline</button></>:row.status!=="REJECTED"&&<button disabled={pending} className={s.secondary} onClick={()=>setConfirm(row.relationshipId)}>{row.status==="PENDING"?"Cancel request":"End feature"}</button>}</div>{confirm===row.relationshipId&&<div className={s.reply}><p className={s.muted}>This removes the item from the partner display. The original listing stays available, and a new request can be sent later.</p><div className={s.miniLinks}><button disabled={pending} className={s.button} onClick={()=>run(()=>removeCrossStoreFeature(row.relationshipId),"Feature closed. A new request can be made later.")}>{pending?"Saving…":"Confirm"}</button><button className={s.secondary} disabled={pending} onClick={()=>setConfirm(null)}>Keep it</button></div></div>}</article>)}</div></section>
 </div>;
}
